#include "tigersheets/financial_example.hpp"
#include "tigersheets/session.hpp"
#include "tigersheets/analysis.hpp"
#include <cmath>
#include <iostream>
#include <stdexcept>
using namespace tigersheets;
void require(bool value,const char* message){if(!value)throw std::runtime_error(message);}
double numberAt(const Json& calculated,const std::string& sheet,int row,int col){for(const auto& value:calculated.at("values"))if(value.at("sheet")==sheet&&value.at("row")==row&&value.at("col")==col)return value.at("value");throw std::runtime_error("missing example result");}
int main(){try{WorkbookSession session;const auto original=session.snapshot();const auto operations=financialExampleOperations(original);require(session.snapshotView()==original,"example preparation preserves user's live workbook");std::string error;const bool applied=session.apply(0,operations,&error);require(applied,error.c_str());const auto& book=session.snapshotView();require(book.at("sheets").size()==3&&book.at("sheets")[0]==original.at("sheets")[0],"example appends two sheets while retaining existing work");CalculationEngine engine;const auto calculated=engine.calculate(book);const auto model=book.at("sheets")[2].at("id").get<std::string>();require(calculated.at("status")=="ok"&&std::abs(numberAt(calculated,model,6,2)-50.0/0.9)<1e-6,"circular financing example converges debt and interest through shared scheduler");const auto goal=book.at("financialModels")[2];require(goal.at("kind")=="goal_seek","example contains a saved Goal Seek workflow");CalculationContext context;context.snapshot=book;const auto solution=goalSeekWorkbook(book,goal.at("specification"),&context);require(solution.at("success")==true&&std::abs(solution.at("value").get<double>()-114)<1e-5,"example Goal Seek solves cash114 for target debt40");require(session.undo()&&session.snapshotView().at("sheets").size()==1,"one undo removes example and settings together");auto occupied=original;occupied["sheets"][0]["name"]="finance assumptions";occupied["financialModels"]=Json::array({{{"version",1},{"id","existing"},{"name","base financing"},{"kind","assumption_set"},{"cells",Json::array({{{"sheet","sheet-1"},{"row",1},{"col",1},{"type","blank"},{"value",nullptr}}})}}});WorkbookSession existing(occupied);const auto appended=financialExampleOperations(occupied);const bool uniqueNames=existing.apply(0,appended,&error);require(uniqueNames,"example chooses case-insensitively unique worksheet and saved setup names");std::cout<<"financial example tests passed\n";}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
